//! A three-way line merge — the thing that makes a record mergeable at all.
//!
//! ── WHY A RECORD CANNOT BE MERGED BY GIT TODAY ──────────────────────────────────────────────────
//! A record is stored as JSON and its whole module body lives on ONE line of it: measured across
//! `graph/records/`, a file is 11-27 LINES but 23-37 KILOBYTES. So two sessions editing different
//! functions of the same module both change that single `code` line, and git — which merges by line —
//! reports a conflict over 23 KB of unsplittable text. Nobody resolves that by hand.
//!
//! Splitting the store into one file per record fixed merging BETWEEN records and did nothing for
//! WITHIN one, because the granularity that matters was never the file. This module is the missing
//! half: unescape the body back into real lines, merge those, and a normal source conflict comes out
//! the other side.
//!
//! ── THE ALGORITHM, AND WHY THIS ONE ─────────────────────────────────────────────────────────────
//! Classic diff3. Match each side against the BASE, walk the three in step, and emit:
//!
//!   * a STABLE run — all three agree — verbatim;
//!   * a region only OURS changed → ours;
//!   * a region only THEIRS changed → theirs;
//!   * a region both changed IDENTICALLY → either;
//!   * anything else → a conflict, marked the way git marks one, so a human sees a shape they know.
//!
//! It is deliberately not a smarter merge. A merge driver that resolves cleverly is a merge driver
//! that loses work quietly, and this one's job is to be RIGHT about the easy majority and HONEST about
//! the rest.

/// One matched pair of line indices between two sequences.
type Match = (usize, usize);

/// Longest common subsequence as matched index pairs, by the standard dynamic program.
///
/// O(n·m) in time and memory, which is the right trade here: a record body is source code — the
/// largest in this store is under 2,000 lines — and an approximate matcher would make the merge
/// non-deterministic across versions of itself, which a merge driver must never be.
fn lcs(a: &[&str], b: &[&str]) -> Vec<Match> {
    let (n, m) = (a.len(), b.len());
    let mut dp = vec![0u32; (n + 1) * (m + 1)];
    let at = |i: usize, j: usize| i * (m + 1) + j;
    for i in (0..n).rev() {
        for j in (0..m).rev() {
            dp[at(i, j)] = if a[i] == b[j] {
                dp[at(i + 1, j + 1)] + 1
            } else {
                dp[at(i + 1, j)].max(dp[at(i, j + 1)])
            };
        }
    }
    let (mut i, mut j, mut out) = (0, 0, Vec::new());
    while i < n && j < m {
        if a[i] == b[j] {
            out.push((i, j));
            i += 1;
            j += 1;
        } else if dp[at(i + 1, j)] >= dp[at(i, j + 1)] {
            i += 1;
        } else {
            j += 1;
        }
    }
    out
}

/// The outcome of a merge: the text, and how many regions could not be resolved.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Merged {
    pub text: String,
    pub conflicts: usize,
}

/// Merge `ours` and `theirs` over their common `base`.
///
/// `labels` names the three sides in a conflict block — git passes the branch names, and a conflict
/// that says `<<<<<<< ours` teaches nothing.
pub fn merge3(base: &str, ours: &str, theirs: &str, labels: (&str, &str), marker: usize) -> Merged {
    // Fast paths that are not optimizations but CORRECTNESS: a side that did not change must never
    // contribute a conflict, and identical sides must never produce one either.
    if ours == theirs {
        return Merged { text: ours.to_string(), conflicts: 0 };
    }
    if base == ours {
        return Merged { text: theirs.to_string(), conflicts: 0 };
    }
    if base == theirs {
        return Merged { text: ours.to_string(), conflicts: 0 };
    }

    let bl: Vec<&str> = base.split_inclusive('\n').collect();
    let ol: Vec<&str> = ours.split_inclusive('\n').collect();
    let tl: Vec<&str> = theirs.split_inclusive('\n').collect();

    // base index -> index on that side, for the lines each side kept.
    let mut o_of = vec![usize::MAX; bl.len()];
    for (b, o) in lcs(&bl, &ol) {
        o_of[b] = o;
    }
    let mut t_of = vec![usize::MAX; bl.len()];
    for (b, t) in lcs(&bl, &tl) {
        t_of[b] = t;
    }

    let m = "=".repeat(marker.max(7));
    let lt = "<".repeat(marker.max(7));
    let gt = ">".repeat(marker.max(7));
    let mid = "|".repeat(marker.max(7));

    let mut out = String::with_capacity(ours.len().max(theirs.len()));
    let mut conflicts = 0usize;
    let (mut bi, mut oi, mut ti) = (0usize, 0usize, 0usize);

    while bi < bl.len() {
        // A STABLE line: kept by both sides, and both sides are standing exactly there.
        if o_of[bi] != usize::MAX && t_of[bi] != usize::MAX && o_of[bi] == oi && t_of[bi] == ti {
            out.push_str(bl[bi]);
            bi += 1;
            oi += 1;
            ti += 1;
            continue;
        }
        // Otherwise the three have diverged. Find the next base line all three agree on again —
        // that bounds the region each side rewrote.
        let mut nb = bi + 1;
        while nb < bl.len() && !(o_of[nb] != usize::MAX && t_of[nb] != usize::MAX) {
            nb += 1;
        }
        let (no, nt) = if nb < bl.len() { (o_of[nb], t_of[nb]) } else { (ol.len(), tl.len()) };
        let ours_region: String = ol[oi.min(no)..no].concat();
        let theirs_region: String = tl[ti.min(nt)..nt].concat();
        let base_region: String = bl[bi..nb].concat();

        if ours_region == theirs_region {
            out.push_str(&ours_region); // both made the same edit
        } else if ours_region == base_region {
            out.push_str(&theirs_region); // only theirs changed
        } else if theirs_region == base_region {
            out.push_str(&ours_region); // only ours changed
        } else {
            conflicts += 1;
            out.push_str(&format!("{lt} {}\n", labels.0));
            out.push_str(&ours_region);
            if !ours_region.ends_with('\n') {
                out.push('\n');
            }
            out.push_str(&format!("{mid} base\n"));
            out.push_str(&base_region);
            if !base_region.is_empty() && !base_region.ends_with('\n') {
                out.push('\n');
            }
            out.push_str(&format!("{m}\n"));
            out.push_str(&theirs_region);
            if !theirs_region.ends_with('\n') {
                out.push('\n');
            }
            out.push_str(&format!("{gt} {}\n", labels.1));
        }
        bi = nb;
        oi = no;
        ti = nt;
    }

    // Whatever either side appended past the last shared line.
    if oi < ol.len() || ti < tl.len() {
        let ours_tail: String = ol[oi.min(ol.len())..].concat();
        let theirs_tail: String = tl[ti.min(tl.len())..].concat();
        if ours_tail == theirs_tail {
            out.push_str(&ours_tail);
        } else if ours_tail.is_empty() {
            out.push_str(&theirs_tail);
        } else if theirs_tail.is_empty() {
            out.push_str(&ours_tail);
        } else {
            conflicts += 1;
            out.push_str(&format!("{lt} {}\n", labels.0));
            out.push_str(&ours_tail);
            out.push_str(&format!("{m}\n"));
            out.push_str(&theirs_tail);
            out.push_str(&format!("{gt} {}\n", labels.1));
        }
    }

    Merged { text: out, conflicts }
}

#[cfg(test)]
mod merge3_tests {
    use super::*;
    fn m(b: &str, o: &str, t: &str) -> Merged { merge3(b, o, t, ("ours", "theirs"), 7) }

    #[test] fn identical_sides_never_conflict() {
        let r = m("a\nb\n", "a\nX\n", "a\nX\n");
        assert_eq!(r.conflicts, 0); assert_eq!(r.text, "a\nX\n");
    }
    #[test] fn only_ours_changed() {
        let r = m("a\nb\nc\n", "a\nB\nc\n", "a\nb\nc\n");
        assert_eq!((r.conflicts, r.text.as_str()), (0, "a\nB\nc\n"));
    }
    #[test] fn only_theirs_changed() {
        let r = m("a\nb\nc\n", "a\nb\nc\n", "a\nb\nC\n");
        assert_eq!((r.conflicts, r.text.as_str()), (0, "a\nb\nC\n"));
    }
    #[test] fn disjoint_edits_both_land() {
        // THE CASE THE WHOLE DRIVER EXISTS FOR: two functions in one module, edited by two sessions.
        let b = "fn a() {}\nfn b() {}\nfn c() {}\n";
        let o = "fn a() { 1 }\nfn b() {}\nfn c() {}\n";
        let t = "fn a() {}\nfn b() {}\nfn c() { 3 }\n";
        let r = m(b, o, t);
        assert_eq!(r.conflicts, 0, "disjoint edits must merge clean: {}", r.text);
        assert_eq!(r.text, "fn a() { 1 }\nfn b() {}\nfn c() { 3 }\n");
    }
    #[test] fn the_same_line_edited_two_ways_conflicts() {
        let r = m("a\nb\nc\n", "a\nOURS\nc\n", "a\nTHEIRS\nc\n");
        assert_eq!(r.conflicts, 1);
        assert!(r.text.contains("<<<<<<< ours"), "{}", r.text);
        assert!(r.text.contains(">>>>>>> theirs"), "{}", r.text);
        assert!(r.text.contains("OURS") && r.text.contains("THEIRS"));
    }
    #[test] fn insertions_at_different_places_both_survive() {
        let b = "1\n2\n3\n";
        let o = "1\nnew-ours\n2\n3\n";
        let t = "1\n2\n3\nnew-theirs\n";
        let r = m(b, o, t);
        assert_eq!(r.conflicts, 0, "{}", r.text);
        assert!(r.text.contains("new-ours") && r.text.contains("new-theirs"), "{}", r.text);
    }
    #[test] fn a_deletion_on_one_side_applies() {
        let r = m("a\nb\nc\n", "a\nc\n", "a\nb\nc\n");
        assert_eq!((r.conflicts, r.text.as_str()), (0, "a\nc\n"));
    }
    #[test] fn no_trailing_newline_is_preserved() {
        let r = m("a\nb", "a\nB", "a\nb");
        assert_eq!((r.conflicts, r.text.as_str()), (0, "a\nB"));
    }
    #[test] fn empty_base_with_both_adding_conflicts_honestly() {
        let r = m("", "x\n", "y\n");
        assert_eq!(r.conflicts, 1, "{}", r.text);
    }
    #[test] fn a_realistic_module_merges_by_function() {
        let b = (0..60).map(|i| format!("line {i}\n")).collect::<String>();
        let mut o: Vec<String> = (0..60).map(|i| format!("line {i}\n")).collect();
        o[5] = "line 5 EDITED BY OURS\n".into();
        let mut t: Vec<String> = (0..60).map(|i| format!("line {i}\n")).collect();
        t[50] = "line 50 EDITED BY THEIRS\n".into();
        let r = m(&b, &o.concat(), &t.concat());
        assert_eq!(r.conflicts, 0, "60-line module, two distant edits: {}", r.text);
        assert!(r.text.contains("EDITED BY OURS") && r.text.contains("EDITED BY THEIRS"));
    }
}
